function getJS(){
  try { var els=document.querySelectorAll('tw-passagedata[tags~=script], tw-passagedata'); } catch(e){}
  // pull all script-tagged story passages from the storydata
  var sd=document.querySelector('tw-storydata');
  var js='';
  if(sd){ var nodes=sd.querySelectorAll('tw-passagedata'); 
    nodes.forEach(function(n){ var t=n.getAttribute('tags')||''; if(t.indexOf('script')>-1){ js+='\n/*== '+n.getAttribute('name')+' ==*/\n'+n.textContent; } });
  }
  return js;
}
